// 有界页面保留原Offer条款及本人受领史，不显示远方sender位置、钱包余额或新的委托知识。
#include "task_personal_acceptance_view.hpp"
#include "task_personal_acceptance_detail.hpp"
namespace hanmo::resident {namespace {
BoundaryValue identity_value(const WorldIdentity& i){using V=BoundaryValue;StableId world;const char* hex="0123456789abcdef";for(auto byte:i.world_id){world.push_back(hex[byte>>4]);world.push_back(hex[byte&15]);}return boundary::obj({{"world_id",V{world}},{"execution_epoch",V{i.execution_epoch}},{"revision",V{i.revision}},{"tick",V{i.tick}}});}
}
Outcome<BoundaryValue> query_task_personal_acceptances(const TaskPersonalAcceptanceServices& service,Integer cursor){using V=BoundaryValue;const auto& x=service.sources;const auto& c=x.common;const auto actor=c.state().metadata.player_actor_id;if(x.phase)return {false,{},common_failure("TaskPersonalAcceptanceStableQueryRequired").error};if(!c.actor(actor))return {false,{},common_failure("UnknownActor").error};auto valid=validate_task_personal_acceptances(x);if(!valid.ok)return {false,{},valid.error};std::vector<const TaskPersonalAcceptancePolicy*> known;
 for(const auto& p:x.catalog.policies){auto source=personal_acceptance_detail::known_offer(x,actor,p.offer_id,c.tick());if(!source.ok){if(source.error.original.code=="SourceUnknown")continue;return {false,{},source.error};}known.push_back(&p);}
 if(cursor<0||static_cast<std::size_t>(cursor)>known.size())return {false,{},common_failure("InvalidTaskPersonalAcceptanceCursor").error};V::Array rows;Integer next=cursor;
 for(;static_cast<std::size_t>(next)<known.size()&&rows.size()<16;++next){const auto& p=*known[static_cast<std::size_t>(next)];const auto* offer=x.task_catalog.offers.find(p.offer_id);if(!offer)return {false,{},common_failure("TaskPersonalAcceptanceOriginalSourcesRequired",p.offer_id).error};auto knowledge=personal_acceptance_detail::known_offer(x,actor,p.offer_id,c.tick());if(!knowledge.ok)return {false,{},knowledge.error};const TaskPersonalAcceptanceStart* latest=nullptr;for(const auto& row:x.state.starts.rows())if(row.second.offer_id==p.offer_id&&row.second.carrier_actor_id==actor)latest=&row.second;const auto* end=latest?personal_acceptance_detail::end_for_start(x.state,latest->fact_id):nullptr;const auto* task=latest?x.tasks.tasks.find(latest->task_id):nullptr;
  StableId status="已知原委托，尚未受领";if(latest)status=end?(end->success?"已受领原信件和预算":"这次受领未完成"):"正在向原发信本人受领";if(task&&(task->status=="success"||task->status=="cancelled"||task->status=="failed"))status=task->status=="success"?"原委托已返报结酬":"原委托已终结";
  auto q=preview_task_personal_acceptance(x,service.interaction_access,actor,{p.offer_id});V::Array actions;actions.push_back(boundary::obj({{"command",V{StableId{task_personal_acceptance_command}}},{"params",boundary::obj({{"offer_id",V{p.offer_id}}})},{"available",V{q.ok}},{"code",V{q.ok?StableId{}:q.error.original.code}},{"text",V{StableId{"向原发信本人受领"}}},{"summary",V{StableId{"须发信本人在当前会面明确声明。办理一半日，由原任务发放原信件和预算；交信、返报或销约仍按原责任办理。"}}}}));
  rows.push_back(boundary::obj({{"id",V{p.offer_id}},{"offer_id",V{p.offer_id}},{"display_name",V{offer->display_name}},{"sender_actor_id",V{offer->issuer.id}},{"recipient_actor_id",V{offer->goal.receiver_actor}},{"task_id",V{latest?latest->task_id:StableId{}}},{"status_text",V{status}},{"observed_tick",V{end?end->tick:latest?latest->started_tick:knowledge.value.discovered_tick}},{"source_fact_id",V{end?end->fact_id:latest?latest->fact_id:StableId{}}},{"terms_text",V{StableId{"委托预算："+std::to_string(offer->budget)+"；完成报酬："+std::to_string(offer->reward)+"；原期限："+std::to_string(offer->deadline_ticks)+"半日。受领办理需半日，原报酬在送达并返报后结算。"}}},{"budget",V{offer->budget}},{"reward",V{offer->reward}},{"deadline_ticks",V{offer->deadline_ticks}},{"actions",V{std::move(actions)}}}));
 }
 V::Dict page{{"ok",V{true}},{"enabled",V{true}},{"source_identity",identity_value(c.state().identity)},{"observer_actor_id",V{actor}},{"cursor",V{cursor}},{"rows",V{std::move(rows)}}};if(static_cast<std::size_t>(next)<known.size())page.emplace_back("next_cursor",V{next});return {true,V{std::move(page)},{}};
}
}
